# --------------------------------------------------------------------------
# Public-site boundary: no household model or personal case data is imported.
# Inputs, estimates and recommendations belong only in an offline private file.
# --------------------------------------------------------------------------


def content_for(path: str) -> tuple[str, str, str]:
    """Return generic guidance only; household figures are never built here."""
    if path == "pages/model-figures.html":
        rows = [
            (["Property value, rent, debt, basis and costs", "Not collected or published", "Obtain independent written records and enter them only in a private offline model."], STATUS["missing"], ["irs_basis", "irs_rental"]),
            (["Tax and assessment rules", "Rule and deadline summaries only; household eligibility and liability remain uncomputed.", "Confirm the operative-year law and obtain written advice from the relevant authority or adviser."], STATUS["guidance"], ["ca_rtc51", "ca_rtc63", "irs_estate"]),
            (["Projected values and path ranking", "No public household projection or recommendation.", "Compare all paths privately at the same transfer date and horizon, with ranges and documented assumptions."], STATUS["guidance"], ["cbo_long", "fhfa", "sec_stocks"]),
        ]
        return "Model figures and provenance", "No case inputs or property-specific projection is stored or published by this site.", table("Public data boundary", ["Input or output", "Public status", "Private next step"], rows)
    if path == "pages/economic-baselines.html":
        rows = [
            (["Inflation", "Historical variation is observable; it is not a 50-year forecast.", "Use multiple inflation regimes and disclose each assumption."], STATUS["guidance"], ["bls_cpi"]),
            (["Housing", "National and regional indices describe broad historical movements, not an individual property's future value.", "Use independent valuation evidence and low/base/high scenarios."], STATUS["guidance"], ["fhfa"]),
            (["Equities and drawdowns", "Historical sequences vary; average return alone hides entry-date risk.", "Test adverse sequences near transfer and subsequent recovery periods."], STATUS["guidance"], ["sec_stocks", "fed_1929"]),
            (["Long-run public projections", "Agency outlooks have finite horizons and are not household investment forecasts.", "Do not extend a short-range forecast unchanged across a multi-decade horizon."], STATUS["guidance"], ["cbo_long"]),
        ]
        body = table("Economic evidence and limits", ["Driver", "What the source can establish", "Private-model treatment"], rows)
        body += prose("Regime method", "Model distinct growth, inflation, interest-rate, recession, recovery and deflation blocks. Stress entry immediately before a severe decline, compare immediate investing with a Treasury ladder, and show both the protection from an early fall and the opportunity cost if markets rise during staging. These are sensitivities, not forecasts.")
        return "Economic baselines", "Long horizons require more than one growth rate; official historical sources provide context, not certainty.", body
    return base_content_for(path)


def render(path: str, title: str, group: str) -> str:
    root = path == "index.html"
    prefix = "" if root else "../"
    page_path = path
    heading, lead, body = content_for(page_path)
    nav = []
    groups: dict[str, list[tuple[str, str]]] = {}
    for file, label, section in PAGES:
        groups.setdefault(section, []).append((file, label))
    for section, items in groups.items():
        nav.append(f'<details class="nav-group" open><summary>{esc(section)}</summary><div class="nav-items">')
        for file, label in items:
            href = prefix + file
            current = ' aria-current="page"' if file == path else ""
            nav.append(f'<a href="{esc(href)}"{current}>{esc(label)}</a>')
        nav.append('</div></details>')
    nav_html = ''.join(nav)
    title_full = f"{esc(heading)} · Inheritance decision guide"
    body_class = ' class="brief-page"' if path.endswith("attorney-cpa-brief.html") else ""
    doc = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer">
<meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'">
<meta name="description" content="Generic, source-linked inheritance decision guide. No household inputs or property-specific projections are published.">
<title>{title_full}</title><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/phase-model.js" defer></script><script src="{prefix}assets/regime-model.js" defer></script><script src="{prefix}assets/app.js" defer></script></head>
<body{body_class}><a class="skip" href="#main">Skip to content</a><div class="layout"><aside class="sidebar"><a class="brand" href="{prefix}index.html"><span class="brand-icon" aria-hidden="true">◈</span><span>INHERITANCE<br>DECISION GUIDE</span></a><p class="sidebar-note">Inheritance planning<br>decision guide</p><nav aria-label="Main navigation">{nav_html}</nav><div class="sidebar-bottom">No household inputs or identifiers<br>Official sources linked by scope<br>Private work stays offline</div></aside>
<div class="workspace"><header class="topbar"><span>RESEARCH / DECISION SUPPORT</span><div><span class="privacy-dot" aria-hidden="true"></span> Privacy-first <button class="print-button no-print" id="print-page" type="button">Print</button></div></header>
<main id="main"><div class="page-heading"><span class="eyebrow">{esc(group.upper())}</span><h1>{esc(heading)}</h1><p class="lead">{esc(lead)}</p></div>{body}</main>
<footer class="site-footer"><p>Research framework only; not legal, tax, insurance, appraisal, investment, or property-management advice.</p><p>Recheck official authorities, source availability and law at the actual decision date.</p></footer></div></div></body></html>'''
    return doc.replace("__ROOT__", prefix)


def build() -> None:
    (ROOT / "assets").mkdir(exist_ok=True)
    (ROOT / "pages").mkdir(exist_ok=True)
    for path, title, group in PAGES:
        target = ROOT / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(render(path, title, group), encoding="utf-8")
    (ROOT / "tools/site-manifest.json").write_text(json.dumps([p for p, _, _ in PAGES], indent=2) + "\n", encoding="utf-8")
    print(f"Built {len(PAGES)} generic pages; no household model or private input file read.")

if __name__ == "__main__":
    build()
